#include <madron/timbre/PartialTracker.h>

#include <algorithm>
#include <cmath>
#include <numbers>

namespace madron::timbre {
bool PartialTracker::prepare(const double sampleRate) { if(sampleRate<=0.0||!fft_.prepare(analysisSize))return false;sampleRate_=sampleRate;for(std::size_t i=0;i<analysisSize;++i)window_[i]=0.5f-0.5f*std::cos(2.0f*std::numbers::pi_v<float>*static_cast<float>(i)/static_cast<float>(analysisSize));reset();return true; }
void PartialTracker::reset() noexcept {ring_.fill(0.0f);spectrum_.fill({});tracks_.fill({});events_.fill({});write_=seen_=sinceHop_=eventRead_=eventWrite_=0;nextTrackId_=1;sampleTime_=0;decimationSum_=previousDecimated_=periodHint_=0.0f;decimationCount_=0;lastPositiveCross_=0;}
void PartialTracker::push(const float raw) noexcept {const float sample=std::isfinite(raw)?raw:0.0f;ring_[write_]=sample;write_=(write_+1)%analysisSize;++seen_;++sinceHop_;++sampleTime_;decimationSum_+=sample;if(++decimationCount_==8){const float d=decimationSum_/8.0f;if(previousDecimated_<=0.0f&&d>0.0f){if(lastPositiveCross_>0){const auto elapsed=sampleTime_-lastPositiveCross_;if(elapsed>16&&elapsed<sampleRate_/5.0)periodHint_=static_cast<float>(elapsed);}lastPositiveCross_=sampleTime_;}previousDecimated_=d;decimationSum_=0.0f;decimationCount_=0;}if(seen_>=analysisSize&&sinceHop_>=hopSize){sinceHop_=0;analyseFrame();}}
bool PartialTracker::pop(PartialEvent& event) noexcept {if(eventRead_==eventWrite_)return false;event=events_[eventRead_];eventRead_=(eventRead_+1)%events_.size();return true;}
void PartialTracker::analyseFrame() noexcept {
    for(std::size_t i=0;i<analysisSize;++i)spectrum_[i]={ring_[(write_+i)%analysisSize]*window_[i],0.0f};fft_.transform(spectrum_,false);struct Peak{float frequency,amplitude;};std::array<Peak,maximumPeaks> peaks{};std::size_t count=0;const std::size_t maximumBin=std::min<std::size_t>(analysisSize/2-1,static_cast<std::size_t>(8000.0*analysisSize/sampleRate_));
    for(std::size_t k=2;k<maximumBin;++k){const float left=std::abs(spectrum_[k-1]),mid=std::abs(spectrum_[k]),right=std::abs(spectrum_[k+1]);if(mid<=left||mid<right)continue;const float denom=left-2.0f*mid+right;const float offset=std::abs(denom)>1.0e-12f?std::clamp(0.5f*(left-right)/denom,-0.5f,0.5f):0.0f;Peak candidate{(static_cast<float>(k)+offset)*static_cast<float>(sampleRate_)/static_cast<float>(analysisSize),2.0f*mid/static_cast<float>(analysisSize)};std::size_t position=std::min(count,maximumPeaks);while(position>0&&candidate.amplitude>peaks[position-1].amplitude){if(position<maximumPeaks)peaks[position]=peaks[position-1];--position;}if(position<maximumPeaks){peaks[position]=candidate;if(count<maximumPeaks)++count;}}
    for(auto& track:tracks_)if(track.active)++track.missed;
    for(std::size_t p=0;p<count;++p){auto peak=peaks[p];if(periodHint_>0.0f){const float hint=static_cast<float>(sampleRate_)/periodHint_;if(peak.frequency>hint*0.5f&&peak.frequency<hint*2.0f)peak.frequency=0.75f*peak.frequency+0.25f*hint;}Track* match=nullptr;float distance=0.08f;for(auto& track:tracks_)if(track.active){const float d=std::abs(track.frequency-peak.frequency)/std::max(1.0f,peak.frequency);if(d<distance){distance=d;match=&track;}}if(match==nullptr)for(auto& track:tracks_)if(!track.active){match=&track;match->id=nextTrackId_++;break;}if(match==nullptr)continue;const bool start=!match->active;match->active=true;match->missed=0;match->frequency=peak.frequency;match->amplitude=std::clamp(peak.amplitude,0.0f,1.0f);const auto next=(eventWrite_+1)%events_.size();if(next!=eventRead_){events_[eventWrite_]={match->frequency,match->amplitude,match->id,0,0,start?PartialEventType::Start:PartialEventType::Update,sampleTime_};eventWrite_=next;}}
    for(auto& track:tracks_)if(track.active&&track.missed>2){const auto next=(eventWrite_+1)%events_.size();if(next!=eventRead_){events_[eventWrite_]={track.frequency,0.0f,track.id,0,0,PartialEventType::Stop,sampleTime_};eventWrite_=next;}track.active=false;}
}
} // namespace madron::timbre
